   495	function readWorkerProposalInvocationPrivateKey(
   496	  env: NodeJS.ProcessEnv,
   497	): string | undefined {
   498	  const rawFd = env.LATTICE_MANAGED_HOST_WORKER_CAPABILITY_FD?.trim();
   499	  if (!rawFd) return undefined;
   500	  const fd = Number(rawFd);
   501	  if (!Number.isInteger(fd) || fd < 3 || fd > 255) {
   502	    throw new Error('managed host run worker: proposal capability fd must be between 3 and 255');
   503	  }
   504	  const stat = fstatSync(fd);
   505	  if (stat.isFile()) {
   506	    throw new Error('managed host run worker: proposal capability must arrive over a non-file descriptor');
   507	  }
   508	  const key = readFileSync(fd, 'utf8').trim();
   509	  if (!/^[A-Za-z0-9+/]{43}=$/.test(key)) {
   510	    throw new Error('managed host run worker: proposal capability descriptor is malformed');
   511	  }
   512	  return key;
   513	}
