   542	function canonicalJson(value: unknown): string {
   543	  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
   544	  if (value && typeof value === 'object') {
   545	    const entries = Object.entries(value as Record<string, unknown>)
   546	      .filter(([, item]) => item !== undefined)
   547	      .sort(([left], [right]) => left.localeCompare(right));
   548	    return `{${entries.map(([key, item]) => `${JSON.stringify(key)}:${canonicalJson(item)}`).join(',')}}`;
   549	  }
   550	  return JSON.stringify(value);
   551	}
