   655	async function withManagedReconcileLock<T>(
   656	  paths: ManagedHostRunPaths,
   657	  fn: () => Promise<T>,
   658	): Promise<T> {
   659	  const previous = managedReconcileQueues.get(paths.reconcileLock) ?? Promise.resolve();
   660	  let releaseTurn!: () => void;
   661	  const turn = new Promise<void>(resolve => { releaseTurn = resolve; });
   662	  const tail = previous.then(() => turn);
   663	  managedReconcileQueues.set(paths.reconcileLock, tail);
   664	  await previous;
   665	  let lock: ReturnType<typeof acquireMkdirLock> | null = null;
   666	  try {
   667	    lock = acquireMkdirLock(paths.reconcileLock, {
   668	      label: `managed reconcile ${paths.dir}`,
   669	      deadlineMs: 5_000,
   670	      staleMs: 2_000,
   671	      pollMs: 10,
   672	      requireHolderToken: true,
   673	      classifyExistingLock: classifyManagedHostRunTerminalLock,
   674	      holderInfo: {
   675	        pid: process.pid,
   676	        hostname: hostname(),
   677	        command: `managed reconcile ${paths.dir}`,
   678	        acquiredAt: new Date().toISOString(),
   679	        lockId: randomUUID(),
   680	        processStartTimeMs: currentProcessStartTimeMs(),
   681	      },
   682	    });
   683	    return await fn();
   684	  } finally {
   685	    lock?.release();
   686	    releaseTurn();
   687	    if (managedReconcileQueues.get(paths.reconcileLock) === tail) {
   688	      managedReconcileQueues.delete(paths.reconcileLock);
   689	    }
   690	  }
   691	}
