   697	function readBoundedUtf8(path: string, maxBytes: number): { text: string; truncated: boolean } {
   698	  const fd = openSync(path, 'r');
   699	  try {
   700	    const buffer = Buffer.allocUnsafe(maxBytes + 1);
   701	    const bytesRead = readSync(fd, buffer, 0, buffer.length, 0);
   702	    return {
   703	      text: buffer.subarray(0, Math.min(bytesRead, maxBytes)).toString('utf8'),
   704	      truncated: bytesRead > maxBytes,
   705	    };
   706	  } finally {
   707	    closeSync(fd);
   708	  }
   709	}
