   720	  try {
   721	    writeFileSync(temp, `${canonicalJson(value)}\n`, { encoding: 'utf8', mode, flag: 'wx' });
   722	    chmodSync(temp, mode);
   723	    linkSync(temp, path);
   724	    return true;
   725	  } catch (error) {
   726	    if ((error as NodeJS.ErrnoException).code === 'EEXIST') return false;
