   818	        || typeof binding.storyId !== 'string'
   819	        || typeof binding.reviewRunId !== 'string'
   820	        || typeof binding.lane !== 'string'
   821	        || typeof binding.importedAt !== 'string'
   822	        || !Array.isArray(binding.importedIds)
   823	        || binding.importedIds.length === 0
   824	        || binding.importedIds.some(value => typeof value !== 'string' || value.length === 0)
