  1900	async function reconcileManagedHostRunUnlocked(
  1901	  paths: ManagedHostRunPaths,
  1902	  now: number,
  1903	  processGroupOps: ManagedHostRunProcessGroupOps = DEFAULT_PROCESS_GROUP_OPS,
  1904	): Promise<void> {
  1905	  if (readTerminal(paths)) return;
  1906	  const spec = readJson<ManagedHostRunSpec>(paths.spec);
  1907	  const fenceLaunchBeforeTerminal = (): 'revoked' | 'granted' | 'spawned' => withTerminalAuthorityLock(paths, () => {
  1908	    const current = readJson<ManagedHostRunSnapshot>(paths.snapshot);
  1909	    const state = current.providerLaunchState
  1910	      ?? (current.providerIdentity ? 'spawned' : current.state === 'submitted' ? 'pending' : 'granted');
  1911	    if (state === 'pending' || state === 'revoked') {
  1912	      if (state === 'pending') {
  1913	        updateSnapshotUnlocked(paths, value => ({ ...value, providerLaunchState: 'revoked' }));
  1914	      }
  1915	      return 'revoked';
  1916	    }
  1917	    return state;
  1918	  });
  1919	  if (now >= Date.parse(spec.deadlineAt)) {
  1920	    const request = ensureCancelRequest(paths, spec.runId, 'absolute_deadline_exceeded', now);
  1921	    // Give a healthy worker a short cooperative window. A genuinely wedged
  1922	    // worker cannot hold the status API forever: after the grace, the next touch
  1923	    // reconciles against the recorded provider identity and writes an honest
  1924	    // terminal even when replacement safety cannot be proven.
  1925	    if (now - Date.parse(request.requestedAt) < 250) return;
  1926	    const launchState = fenceLaunchBeforeTerminal();
  1927	    const fencedSnapshot = readJson<ManagedHostRunSnapshot>(paths.snapshot);
  1928	    const cleanup = launchState === 'revoked'
  1929	      ? REAPED_WITHOUT_SIGNAL
  1930	      : fencedSnapshot.providerIdentity
  1931	        ? await reapManagedHostRunProviderProcess(fencedSnapshot.providerIdentity, processGroupOps)
  1932	        : AMBIGUOUS_PROCESS_CLEANUP;
