  1934	      paths,
  1935	      'timed_out',
  1936	      'absolute_deadline_exceeded',
  1937	      cleanupIsReplacementSafe(cleanup),
  1938	      null,
  1939	      now,
  1940	      cleanup,
  1941	    );
  1942	    return;
  1943	  }
  1944	  const cancel = readCancelRequest(paths);
  1945	  if (cancel && now - Date.parse(cancel.requestedAt) >= 250) {
  1946	    const launchState = fenceLaunchBeforeTerminal();
  1947	    const fencedSnapshot = readJson<ManagedHostRunSnapshot>(paths.snapshot);
  1948	    if (launchState === 'granted'
  1949	      && fencedSnapshot.providerIdentity === null
  1950	      && fencedSnapshot.workerPid !== null
  1951	      && pidAlive(fencedSnapshot.workerPid)) return;
  1952	    const cleanup = launchState === 'revoked'
  1953	      ? REAPED_WITHOUT_SIGNAL
  1954	      : fencedSnapshot.providerIdentity
  1955	        ? await reapManagedHostRunProviderProcess(fencedSnapshot.providerIdentity, processGroupOps)
  1956	        : AMBIGUOUS_PROCESS_CLEANUP;
  1957	    const terminal = classifyManagedHostRunCancellation(cancel.reason);
  1958	    writeTerminal(
  1959	      paths,
  1960	      terminal.state,
  1961	      terminal.reason,
  1962	      cleanupIsReplacementSafe(cleanup),
  1963	      null,
  1964	      now,
  1965	      cleanup,
  1966	    );
  1967	  }
  1968	}
