   446	/**
   447	 * Scan codex `exec --json` stdout for the LAST `{"type":"turn.completed",
   448	 * "usage":{...}}` event and return its raw usage object (own-property guarded),
   449	 * or null when no turn.completed usage event is present. Line-streamed with a
   450	 * BOUNDED parse buffer: only the current line and the last usage object are held,
   451	 * so a flooding host cannot accumulate per-line state.
   452	 */
   453	export function scanCodexTurnCompletedUsage(stdout: string): unknown | null {
   454	  if (typeof stdout !== 'string' || stdout.length === 0) return null;
   455	  let last: unknown = null;
   456	  let index = 0;
   457	  const len = stdout.length;
   458	  while (index <= len) {
   459	    let newline = stdout.indexOf('\n', index);
   460	    if (newline === -1) newline = len;
   461	    const line = stdout.slice(index, newline).trim();
   462	    index = newline + 1;
   463	    if (line.length > 0) {
   464	      let parsed: unknown;
   465	      try {
   466	        parsed = JSON.parse(line);
   467	      } catch {
   468	        parsed = undefined;
   469	      }
   470	      if (typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed)) {
   471	        const event = parsed as Record<string, unknown>;
   472	        const type = Object.prototype.hasOwnProperty.call(event, 'type') ? event.type : undefined;
   473	        if (type === 'turn.completed') {
   474	          const usage = Object.prototype.hasOwnProperty.call(event, 'usage') ? event.usage : undefined;
   475	          if (typeof usage === 'object' && usage !== null && !Array.isArray(usage)) {
   476	            last = usage;
   477	          }
   478	        }
   479	      }
   480	    }
   481	    if (newline === len) break;
   482	  }
   483	  return last;
   484	}
