   570	
   571	function codexTurnFailedDigest(message: string | null): string {
   572	  if (message === null || message.trim().length === 0) return 'no_error_message';
   573	  let text = message;
   574	  // Drill: when the message itself parses as a JSON object, descend through
   575	  // own `error` object properties (bounded depth) and prefer the DEEPEST own
   576	  // `message` string found; keep the original message when none is extractable.
   577	  let parsed: unknown;
   578	  try {
   579	    parsed = JSON.parse(text);
   580	  } catch {
   581	    parsed = undefined;
   582	  }
   583	  if (typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed)) {
   584	    let node = parsed as Record<string, unknown>;
   585	    let deepest: string | null = null;
   586	    for (let depth = 0; depth < CODEX_TURN_FAILED_NESTED_DEPTH_CAP; depth++) {
   587	      const m = Object.prototype.hasOwnProperty.call(node, 'message') ? node.message : undefined;
   588	      if (typeof m === 'string') deepest = m;
   589	      const err = Object.prototype.hasOwnProperty.call(node, 'error') ? node.error : undefined;
   590	      if (typeof err !== 'object' || err === null || Array.isArray(err)) break;
   591	      node = err as Record<string, unknown>;
   592	    }
   593	    if (deepest !== null && deepest.trim().length > 0) text = deepest;
   594	  }
   595	  // Sanitize: every control-character/whitespace run becomes a single space,
   596	  // then B-3ddc (codex round-1 F2) neutralize parentheses — '(' -> '[' and
   597	  // ')' -> ']' — so an error.message containing ')' or '(' can never close or
   598	  // reopen the enclosing turn_failed(...) reason delimiters (a delimiter-
   599	  // injection guard). The pinned B-3928 upgrade message contains no parens, so
   600	  // its expected reason string is unchanged.
   601	  const sanitized = text.replace(/[\u0000-\u001f\u007f\s]+/g, ' ').replace(/\(/g, '[').replace(/\)/g, ']').trim();
