   603	  if (sanitized.length > CODEX_TURN_FAILED_DIGEST_MAX_CHARS) {
   604	    return `${sanitized.slice(0, CODEX_TURN_FAILED_DIGEST_MAX_CHARS - 1)}…`;
   605	  }
   606	  return sanitized;
   607	}
