   390	function isTolerableTrailingHarness(tail: string): boolean {
   391	  const lines = tail.split('\n').map(l => l.trim()).filter(l => l.length > 0);
   392	  for (const line of lines) {
   393	    if (!HARNESS_NOISE_LINE_PATTERNS.some(pattern => pattern.test(line))) return false;
