      const exitCode = timedOut
        ? 124
        : terminalReason === 'aborted'
          ? 130
          : asyncSpawnError || terminalReason === 'child_error' || terminalReason === 'spawn_error'
            ? 1
            : typeof code === 'number' && code >= 0 ? code : 1;
